var tipuesearch = {"pages": [{"title":"About","text":"\n\n\n\n\n\n\n\r\nall: https://cycu.org/all (包羅萬象)\r\nhealth: https://cycu.org/health (健康)\r\nrecipes: https://cycu.org/recipes (食譜)\r\nclothing: https://cycu.org/clothing (衣著)\r\nliving: https://cycu.org/living (住居)\r\ntourism: https://cycu.org/tourism (旅遊)\r\nlearning: https://cycu.org/learning (學習)\r\ntech: https://cycu.org/tech (科技)\r\nart: https://cycu.org/art (藝術)\r\n","tags":"","url":"About.html"},{"title":"啟動","text":"\r\nportable_rust 啟動 startup.bat:\r\n@echo off\nchcp 65001 >nul\nsetlocal ENABLEEXTENSIONS\n\nREM ==================================================\nREM  Portable System Bootstrap (Rust)\nREM ==================================================\n\nREM === 虛擬磁碟代號（請勿加反斜線）===\nset DRIVE=R:\n\nREM === for Python312\nset PYTHONPATH=%DRIVE%\\Python312\\DLLs;%DRIVE%\\Python312\\Lib;%DRIVE%\\Python312\\Lib\\site-packages;\nREM 將系統 Python 程式的 io 設為 utf-8\nset PYTHONIOENCODING=\"utf-8\"\n\nREM === 取得 batch 所在目錄（結尾含 \\）===\nset ROOT=%~dp0\nset DATA=%ROOT%data\n\nREM === 若已存在則先解除（避免錯誤）===\nsubst %DRIVE% /D >nul 2>&1\n\nREM === 建立虛擬磁碟 ===\nsubst %DRIVE% \"%DATA%\"\n\nREM ==================================================\nREM  Home / User 環境（避免污染系統）\nREM ==================================================\nset HOMEDRIVE=%DRIVE%\nset HOMEPATH=\\home\nset USERPROFILE=%DRIVE%\\home\nset HOME=%DRIVE%\\home\n\nREM ==================================================\nREM  Git / Putty\nREM ==================================================\nset GIT_SSH=%DRIVE%\\PuTTY\\plink.exe\n\nREM ==================================================\nREM  Rust (Portable, GNU)\nREM ==================================================\nset RUSTUP_HOME=%DRIVE%\\.rustup\nREM et CARGO_HOME=%DRIVE%\\.cargo\nREM cargo cache need NTFS disk\nset CARGO_HOME=C:\\cargo\nset SCITE_HOME=%DRIVE%\\wscite\nset RUSTUP_NO_UPDATE_CHECK=1\n\nREM === 強制使用 GNU toolchain ===\nset RUSTUP_TOOLCHAIN=stable-x86_64-pc-windows-gnu\n\nREM === MinGW 編譯器指定（非常重要）===\nset CC=%DRIVE%\\msys64\\ucrt64\\bin\\gcc.exe\nset CXX=%DRIVE%\\msys64\\ucrt64\\bin\\g++.exe\nset AR=%DRIVE%\\msys64\\ucrt64\\bin\\ar.exe\n\nREM === Rust linker 指定 ===\nset RUSTFLAGS=-C linker=%DRIVE%\\msys64\\ucrt64\\bin\\gcc.exe\n\nREM === unveil-rs ===\nset MSYS2=%DRIVE%\\msys64\nset CC=%DRIVE%\\msys64\\ucrt64\\bin\\gcc.exe\nset CXX=%DRIVE%\\msys64\\ucrt64\\bin\\g++.exe\nset CC_x86_64_pc_windows_gnu=%DRIVE%\\msys64\\ucrt64\\bin\\gcc.exe\nset CXX_x86_64_pc_windows_gnu=%DRIVE%\\msys64\\ucrt64\\bin\\g++.exe\n\nREM ==================================================\nREM  PATH 組合\nREM ==================================================\nset PATH=%DRIVE%\\msys64\\ucrt64\\bin^\n;%DRIVE%\\msys64\\usr\\bin^\n;%CARGO_HOME%\\bin^\n;%SCITE_HOME%^\n;%DRIVE%\\portablegit\\bin^\n;%DRIVE%\\Zed\n;%PATH%\n\nREM 以可攜系統中的 Python312 為主\nset PATH=%DRIVE%\\Python312;%DRIVE%\\Python312\\Scripts;%PATH%;%DRIVE%;%DRIVE%\\.rustup\\toolchains\\stable-x86_64-pc-windows-gnu\\bin;\n\nREM ==================================================\nREM  顯示資訊\nREM ==================================================\ntitle Portable Rust GNU Environment (%DRIVE%)\n\necho ======================================\necho  Portable Environment Ready\necho  Mounted Drive : %DRIVE%\necho  Data Path     : %DATA%\necho  Rust Toolchain: %RUSTUP_TOOLCHAIN%\necho  MinGW GCC     : %CC%\necho  Type STOP then close window to exit\necho ======================================\necho.\n\nREM ==================================================\nREM  啟動工具\nREM ==================================================\nif exist \"%SCITE_HOME%\\SciTE.exe\" (\n    start \"\" /MIN \"%SCITE_HOME%\\SciTE.exe\"\n    start \"\" /MIN \"%SCITE_HOME%\\SciTE.exe\"\n)\n\nREM === 切換到虛擬磁碟 ===\n%DRIVE%\n\nREM ==================================================\nREM  保持命令列\nREM ==================================================\nstart /min \"CMD-1\" cmd /k\nstart /min  \"CMD-2\" cmd /k\nstart /min\" CMD-3\" cmd /k\nstart /min \"CMD-4\" cmd /k\n\nREM　啟動 run-rustcms.exe 之後用 firefox 開啟動態網頁編輯\nstart /min \"rustcms\" cmd /k \"cd /d %DRIVE%\\projects\\rustcms && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5000\n\nREM　啟動 all\nstart /min \"all\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\all && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5001\n\nREM　啟動 art\nstart /min \"art\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\art && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5002\n\nREM　啟動 clothing\nstart /min \"clothing\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\clothing && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5003\n\nREM　啟動 health\nstart /min \"health\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\health && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5004\n\nREM　啟動 history\nstart /min \"history\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\history && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5005\n\nREM　啟動 learning\nstart /min \"learning\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\learning && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5006\n\nREM　啟動 living\nstart /min \"living\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\living && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5007\n\nREM　啟動 recipes\nstart /min \"recipes\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\recipes && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5008\n\nREM　啟動 tech\nstart /min \"tech\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\tech && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5009\n\nREM　啟動 tourism\nstart /min \"tourism\" cmd /k \"cd /d %DRIVE%\\projects\\cycuorg\\tourism && cms.exe\"\ntimeout /t 3 /nobreak >nul\nstart \"\" firefox -new-tab https://localhost:5010\n\nREM start /min \"SCMS\" cmd /k \"cd /d %DRIVE%\\tmp\\cmsite && python cms\\wsgi.py\"\nREM start /min \"Leo Editor\" cmd /k \"leo\"\nZed %DRIVE%\\projects\\rustcms\n\nREM start /min %DRIVE%\\Zed\\Zed.exe\n\r\n關閉 stop.bat:\r\n@echo off\nset DRIVE=R:\n\ntaskkill /IM python.exe /F\ntaskkill /IM pythonw.exe /F\nREM taskkill /IM adb.exe /F\ntaskkill /IM scite.exe /F\ntaskkill /IM ugraf.exe /F\ntaskkill /IM webotsw.exe /F\ntaskkill /IM solvespace.exe /F\ntaskkill /IM sharex.exe /F\ntaskkill /IM leo.exe /F\ntaskkill /IM zed.exe /F\ntaskkill /IM cms.exe /F\n\necho Unmounting %DRIVE% ...\nsubst %DRIVE% /D\n\nREM 關閉 cmd 指令視窗\ntaskkill /IM cmd.exe /F\n\necho Done.\n\nEXIT\n\r\n\n","tags":"","url":"啟動.html"},{"title":"代理","text":"\n\n\r\n議題:\r\n如何使用近端 AI 代理整理 CMS 資料? 給定特定類別與主題，由 AI 代理自行尋找資料，整理納入 CMS 系統且自動提交推送到 Github 後回報結果。\n","tags":"","url":"代理.html"},{"title":"Git","text":"\n\n\n\r\n議題:\r\ngit 少量多次推送與集合大量資料後少批推送的差別何在? 比較推薦哪種方式進行資料維護？\r\n\n","tags":"","url":"Git.html"}]};
